```typescript
import { useAppSelector } from '@react-automation-toolkit/hooks';
import { useAppContext } from '@react-automation-toolkit/context';

const useCanvas = () => {
  const context = useAppContext();
  return useAppSelector((state) => ({
    canvas: state.canvas,
  }));
};

export default function Canvas() {
  const { canvas } = useCanvas();

  return <canvas id="canvas" width={canvas.width} height={canvas.height} />;
}
